BEGIN TRANSACTION;
CREATE TABLE answer_cache (key TEXT PRIMARY KEY, created_at TEXT, events TEXT);
CREATE TABLE briefings (id TEXT PRIMARY KEY, at TEXT NOT NULL, question TEXT NOT NULL,
    options TEXT NOT NULL, events TEXT NOT NULL, withdrawn_at TEXT, withdrawn_reason TEXT);
CREATE TABLE failures (id INTEGER PRIMARY KEY, at TEXT, kind TEXT, question TEXT, error TEXT);
CREATE TABLE kv (key TEXT PRIMARY KEY, value TEXT);
CREATE TABLE reports (id INTEGER PRIMARY KEY AUTOINCREMENT, at TEXT NOT NULL, kind TEXT NOT NULL,
    page TEXT, message TEXT NOT NULL, contact TEXT, closed_at TEXT);
CREATE TABLE statements (id INTEGER PRIMARY KEY AUTOINCREMENT, at TEXT NOT NULL, page TEXT NOT NULL,
    country TEXT, name TEXT NOT NULL, role TEXT NOT NULL, text TEXT NOT NULL, link TEXT NOT NULL DEFAULT '',
    email TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'pending', shown_on TEXT, ended_at TEXT, reason TEXT,
    log TEXT NOT NULL DEFAULT '[]');
CREATE TABLE usage (id INTEGER PRIMARY KEY, visitor TEXT, at TEXT, kind TEXT, model TEXT,
    input_tokens INTEGER, output_tokens INTEGER, cache_read_tokens INTEGER, cost_usd REAL,
    cache_write_tokens INTEGER DEFAULT 0);
CREATE INDEX usage_at ON usage (at);
CREATE INDEX statements_page ON statements (status, page);
DELETE FROM "sqlite_sequence";
COMMIT;
